<?php
namespace App\Services\Audit;
use App\Models\ActivityLog; use Illuminate\Database\Eloquent\Model; use Illuminate\Support\Facades\Auth;
class ActivityLogService { public function record(string $module,string $action,?Model $target=null,array $before=[],array $after=[],array $meta=[]): ActivityLog { return ActivityLog::create(['user_id'=>Auth::id(),'module'=>$module,'action'=>$action,'target_type'=>$target?->getMorphClass(),'target_id'=>$target?->getKey()!==null?(string)$target->getKey():null,'document_number'=>$meta['document_number']??null,'ip_address'=>app()->runningInConsole()?null:request()->ip(),'request_path'=>app()->runningInConsole()?null:request()->path(),'before_data'=>$before?json_encode($before,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null,'after_data'=>$after?json_encode($after,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null,'meta_data'=>$meta?json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null,'created_at'=>now()]); } }
